import React from 'react';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  // 💡 අර අඩු වෙලා තිබ්බ 'myCourses' දත්ත ලැයිස්තුව මෙතනට එකතු කළා
  const myCourses = [
    { name: 'Grade 10 - Mathematics', teacher: 'Mr. Perera', status: 'Active' },
    { name: 'Grade 10 - Science', teacher: 'Mrs. Silva', status: 'Active' },
    { name: 'English Literature', teacher: 'Miss. Fernando', status: 'Active' }
  ];

  return (
    <div style={{ padding: '40px', backgroundColor: '#f8fafc', minHeight: '100%' }}>
      <h2 style={{ color: '#388e3c', marginBottom: '30px', fontWeight: '700' }}>
        Student Dashboard - {userName}
      </h2>

      <h3 style={{ color: '#1e293b', marginBottom: '15px' }}>My Enrolled Courses</h3>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '20px' }}>
        {myCourses.map((course, index) => (
          <div key={index} style={{ background: '#fff', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 6px rgba(0,0,0,0.02)', borderTop: '4px solid #388e3c' }}>
            <h4 style={{ margin: '0 0 10px 0', color: '#1e293b', fontSize: '18px' }}>{course.name}</h4>
            <p style={{ margin: '5px 0', color: '#64748b', fontSize: '14px' }}>Teacher: {course.teacher}</p>
            <span style={{ display: 'inline-block', marginTop: '10px', padding: '4px 10px', borderRadius: '20px', backgroundColor: '#e8f5e9', color: '#388e3c', fontSize: '12px', fontWeight: '600' }}>
              {course.status}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
